#!/usr/bin/env bats
load bats-extra


@test "No input" {
    #[[ $BATS_RUN_SKIPPED == "true" ]] || skip
    run gawk -f ocr-numbers.awk /dev/null
    assert_success
    assert_output ""
}

@test "Recognizes 0" {
    [[ $BATS_RUN_SKIPPED == "true" ]] || skip
    run gawk -f ocr-numbers.awk << INPUT
 _ 
| |
|_|

INPUT
    assert_success
    assert_output "0"
}

